import numpy as np
import control as ctrl
import matplotlib.pyplot as plt
from numpy.polynomial import polynomial as poly
plt.rcParams.update({'font.family':'DejaVu Sans','axes.unicode_minus':False})
w=np.logspace(-1,2.5,2001)
def controller(K=20.,wn=10.,zn=.05,zd=.5,a=.1):
    C=K*ctrl.tf([1,2*zn*wn,wn*wn],[1,2*zd*wn,wn*wn])
    return C*ctrl.tf([a],[1,a]) if a>0 else C
def plant(wn=10.):return ctrl.tf([wn*wn],[1,.1*wn,wn*wn])
def squared_poly(coeff):
    q=np.array(coeff)[::-1];even=q[::2]*(-1.)**np.arange(len(q[::2]));odd=q[1::2]*(-1.)**np.arange(len(q[1::2]))
    a=poly.polymul(even,even);b=np.r_[0.,poly.polymul(odd,odd)] if len(odd) else np.array([0.])
    return poly.polyadd(a,b)
def full_frequency_peak(H):
    H=ctrl.minreal(H,verbose=False);N=squared_poly(H.num[0][0]);D=squared_poly(H.den[0][0])
    stationary=poly.polysub(poly.polymul(poly.polyder(N),D),poly.polymul(N,poly.polyder(D)))
    roots=poly.polyroots(poly.polytrim(stationary,tol=1e-7));xs=[0.]+[float(x.real) for x in roots if abs(x.imag)<1e-5*max(1.,abs(x.real)) and x.real>0]
    candidates=[(np.sqrt(max(0.,poly.polyval(x,N)/poly.polyval(x,D))),np.sqrt(x)) for x in xs]
    limit=0. if len(N)<len(D) else np.sqrt(N[-1]/D[-1]);candidates.append((limit,float('inf')))
    return max(candidates,key=lambda pair:pair[0])
def report(C,wn=10.):
    G=plant(wn);L=G*C;S=ctrl.feedback(1,L);T=ctrl.feedback(L,1);alpha=float(max(ctrl.poles(T).real))
    gm,pm,wg,wc=ctrl.margin(L);peak,fpeak=full_frequency_peak(S)
    return {'alpha':alpha,'stable':alpha<0,'frequency_max':float(peak),'peak_frequency':float(fpeak),'Ms':float(peak) if alpha<0 else None,'scan_peak':float(max(abs(S(1j*w)))),'PM':float(pm),'wc':float(wc),'T10':float(abs(T(10j))),'DC_error':float(ctrl.dcgain(S))}

